  ('entitlement:read', 'entitlement', 'read', 'View entitlements', 'See entitlements and pools.', 'Models, spend and policy', 'project', false, false, false, false, false, 1),
  ('entitlement:manage', 'entitlement', 'manage', 'Manage entitlements', 'Connect entitlement sources and their credentials.', 'Models, spend and policy', 'project', true, false, true, false, false, 1),
  ('budget:read', 'budget', 'read', 'View budgets', 'See budget status, forecasts, spend and FinOps.', 'Models, spend and policy', 'project', false, true, false, false, false, 1),
  ('budget:manage', 'budget', 'manage', 'Manage budgets', 'Set caps, intensity and initiative budgets.', 'Models, spend and policy', 'project', true, false, false, false, false, 1),
  ('spend:reserve', 'spend', 'reserve', 'Reserve spend', 'Reserve, consume and release budget for work (runtime only).', 'Models, spend and policy', 'project', false, true, false, true, false, 1),
  ('policy:read', 'policy', 'read', 'View policies', 'See safety, standards, concurrency, token and environment policies.', 'Models, spend and policy', 'project', false, true, false, false, false, 1),
  ('policy:manage', 'policy', 'manage', 'Manage policies', 'Change safety, standards, concurrency, token and environment policies.', 'Models, spend and policy', 'project', true, false, true, false, false, 1),
  ('pipeline:read', 'pipeline', 'read', 'View the coding pipeline', 'See coding-pipeline profiles and adapters.', 'Models, spend and policy', 'project', false, false, false, false, false, 1),
  ('pipeline:manage', 'pipeline', 'manage', 'Manage the coding pipeline', 'Change coding-pipeline profiles and propose pipeline config.', 'Models, spend and policy', 'project', true, false, false, false, false, 1),
  ('secret:read_metadata', 'secret', 'read_metadata', 'View secret metadata', 'See secret references: name, backend, status. Never the value.', 'Secrets and integrations', 'project', false, true, false, false, false, 1),
  ('secret:manage', 'secret', 'manage', 'Manage secrets', 'Create and verify secrets and key pairs.', 'Secrets and integrations', 'project', true, false, true, false, false, 1),
