  ('secret:lease', 'secret', 'lease', 'Lease secrets', 'Lease a secret for a running step (runtime only).', 'Secrets and integrations', 'project', false, true, false, true, false, 1),
  ('app_secret:read_metadata', 'app_secret', 'read_metadata', 'View an app''s secret metadata', 'See an app''s secrets: name, environment, mode and shape. Never the value.', 'Secrets and integrations', 'project', false, true, false, false, false, 1),
  ('app_secret:write', 'app_secret', 'write', 'Set an app''s test secrets', 'Set, replace and remove an app''s test, generated and stub secrets; reveal its test users.', 'Secrets and integrations', 'project', true, false, false, false, false, 1),
  ('app_secret:live', 'app_secret', 'live', 'Use live keys for an app', 'Set an app''s live secrets, used only by a deploy after a person''s decision.', 'Secrets and integrations', 'project', true, false, true, false, false, 1),
  ('app_link:manage', 'app_link', 'manage', 'Link apps', 'Let one app of a project call another''s preview with its test users, and revoke the link.', 'Secrets and integrations', 'project', false, false, false, false, false, 1),
